function createRegistry() {
  const factories = new Map(), cache = new Map()
  const require = (name) => {
    if (cache.has(name)) return cache.get(name)
    if (!factories.has(name)) throw new Error('module not found: ' + name)
    const exports = {}
    cache.set(name, exports)
    factories.get(name)(require, exports)
    return exports
  }
  return { define: (name, f) => factories.set(name, f), require }
}

