function createNotifier(channel) {
  const creators = {
    email: () => ({ send: (m) => `email: ${m}` }),
    sms: () => ({ send: (m) => `sms: ${m.slice(0, 20)}` }),
    push: () => ({ send: (m) => `push: ${m}` }),
  }
  if (!Object.hasOwn(creators, channel)) throw new Error('unknown channel ' + channel)
  return creators[channel]()
}

