class Emitter {
  #m = new Map()
  on(name, fn) {
    const list = this.#m.get(name) ?? []
    list.push(fn); this.#m.set(name, list)
    return () => { const l = this.#m.get(name) ?? []; const i = l.indexOf(fn); if (i >= 0) l.splice(i, 1) }
  }
  once(name, fn) {
    const off = this.on(name, (...a) => { off(); fn(...a) })
    return off
  }
  emit(name, ...args) {
    const list = [...(this.#m.get(name) ?? [])]
    for (const fn of list) fn(...args)
    return list.length
  }
}
